/* v108: bundled study content imported directly from the uploaded workbook; decompressed and installed on the user device. */
(()=>{'use strict';const STORE='liplip-course-content-v2',VK='liplip-bundled-study-content-version',V='108';const DATA='';async function install(){if(localStorage.getItem(VK)===V)return{version:V,installed:false};if(typeof DecompressionStream==='undefined')throw new Error('This browser cannot unpack bundled study content.');const bytes=Uint8Array.from(atob(DATA),c=>c.charCodeAt(0));const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));const raw=await new Response(stream).text();const bundled=JSON.parse(raw);let store={};try{store=JSON.parse(localStorage.getItem(STORE)||'{}')||{}}catch{}for(const [id,c] of Object.entries(bundled))store[id]=c;localStorage.setItem(STORE,JSON.stringify(store));localStorage.setItem(VK,V);window.LiplipBundledStudyContent={version:V,boxes:Object.keys(bundled).length};return{version:V,installed:true,boxes:Object.keys(bundled).length}}window.LiplipBundledStudyContentReady=install().catch(e=>{console.error('[liplip] bundled study content install failed',e);return{version:V,error:String(e?.message||e)}})})();